import SwiftUIstruct TimelineRow: View{    let item: ListItemContent    let isFirst: Bool    let isLast: Bool    let onDelete: (ListItemContent) -> Void        private var isWorkout: Bool {        item.type == .workout    }        var body: some View    {        HStack(alignment: .top, spacing: 14)        {            VStack(spacing: 0)            {                Rectangle()                    .fill(isFirst ? Color.clear : Color.secondary.opacity(0.25))                    .frame(width: 2, height: 8)                                Circle()                    .fill (Color(uiColor: .secondarySystemBackground))                    .frame(width: 38, height: 38)                    .overlay(                        Circle()                            .stroke(Color.primary.opacity(0.08), lineWidth: 1)                    )                    .overlay(                        Text(item.icon)                            .font(.system(size: 18))                    )                                Rectangle()                    .fill(isLast ? Color.clear : Color.secondary.opacity(0.25))                    .frame(width: 2)                    .frame(minHeight: 20)            }            .frame(width: 38)                                    VStack(alignment: .leading, spacing: 4)            {                HStack(alignment: .center, spacing: 6)                {                    Text(item.title)                        .font(.body)                        .fontWeight(.medium)                                        Dot()                                        Text(item.createdAt, format: .dateTime.hour().minute())                        .font(.footnote)                        .foregroundStyle(.secondary)                                        Spacer()                                        Button("delete", systemImage: "xmark")                    {                        onDelete(item)                    }                    .labelStyle(.iconOnly)                    .font(.footnote)                    .tint(.gray.opacity(0.5))                }                                HStack (spacing: 6)                {                    if isWorkout                    {                        Text("-\(item.cals) kcal")                            .font(.footnote)                            .foregroundStyle(.blue)                    } else                    {                        Text("\(item.cals) kcal")                            .font(.footnote)                            .foregroundStyle(.secondary)                    }                                        if item.protein > 0                    {                        Dot()                        Text("\(item.protein) g")                            .font(.footnote)                            .foregroundStyle(.secondary)                    }                }            }            .padding(.top, 6)            .padding(.bottom, 16)        }        .contentShape(Rectangle())        .frame(maxWidth: .infinity, alignment: .leading)    }}